from typing import List


def _runs(A: List[str]):
    """每行的水平极大段 (长度, 行, 起列, 终列)。"""
    res = []
    for r, row in enumerate(A):
        c, m = 0, len(row)
        while c < m:
            if row[c] == '.':
                s = c
                while c < m and row[c] == '.':
                    c += 1
                res.append((c - s, r, s, c - 1))
            else:
                c += 1
    return res


def _mixed(A: List[str]) -> int:
    """一条完整的水平极大段 + 一条与它不相交的竖直段（可截短）的最大总长。"""
    n, m = len(A), len(A[0])
    down = [[0] * m for _ in range(n)]  # 以 (r,c) 为下端的竖直连续长度
    up = [[0] * m for _ in range(n)]    # 以 (r,c) 为上端的竖直连续长度
    for r in range(n):
        for c in range(m):
            if A[r][c] == '.':
                down[r][c] = (down[r - 1][c] if r else 0) + 1
    for r in range(n - 1, -1, -1):
        for c in range(m):
            if A[r][c] == '.':
                up[r][c] = (up[r + 1][c] if r + 1 < n else 0) + 1
    above = [0] * (n + 1)  # above[r]：完全在第 0..r-1 行内的最长竖直段
    for r in range(n):
        above[r + 1] = max(above[r], max(down[r]))
    below = [0] * (n + 1)  # below[r]：完全在第 r..n-1 行内的最长竖直段
    for r in range(n - 1, -1, -1):
        below[r] = max(below[r + 1], max(up[r]))
    col_best = [max(up[r][c] for r in range(n)) for c in range(m)]
    left = [0] * (m + 1)   # left[c]：第 0..c-1 列中的最长竖直段
    for c in range(m):
        left[c + 1] = max(left[c], col_best[c])
    right = [0] * (m + 1)  # right[c]：第 c..m-1 列中的最长竖直段
    for c in range(m - 1, -1, -1):
        right[c] = max(right[c + 1], col_best[c])
    best = 0
    for length, r, a, b in _runs(A):
        # 竖直段与 (r, [a,b]) 不相交 <=> 它整体在该行上方、下方，或在 a 左侧、b 右侧
        best = max(best, length + max(above[r], below[r + 1], left[a], right[b + 1]))
    return best


def maxCells(A: List[str]) -> int:
    T = ["".join(col) for col in zip(*A)]  # 转置后，竖直段变成水平段
    h = sorted((x[0] for x in _runs(A)), reverse=True)
    v = sorted((x[0] for x in _runs(T)), reverse=True)
    if not h:
        return 0
    best = max(h[0] + (h[1] if len(h) > 1 else 0), v[0] + (v[1] if len(v) > 1 else 0))
    return max(best, _mixed(A), _mixed(T))


def _brute(A):
    n, m = len(A), len(A[0])
    segs = [frozenset()]
    for r in range(n):
        for a in range(m):
            for b in range(a, m):
                if all(A[r][c] == '.' for c in range(a, b + 1)):
                    segs.append(frozenset((r, c) for c in range(a, b + 1)))
    for c in range(m):
        for a in range(n):
            for b in range(a, n):
                if all(A[r][c] == '.' for r in range(a, b + 1)):
                    segs.append(frozenset((r, c) for r in range(a, b + 1)))
    return max(len(x) + len(y) for x in segs for y in segs if not (x & y))


if __name__ == "__main__":
    import random
    assert maxCells(["...", "...", "..."]) == 6
    assert maxCells(["###"]) == 0
    assert maxCells([".##", "...", ".##", ".#."]) == 6
    for _ in range(1500):
        n, m = random.randint(1, 5), random.randint(1, 5)
        A = ["".join(random.choice(".#") for _ in range(m)) for _ in range(n)]
        assert maxCells(A) == _brute(A), A
    print("ok")
